INSERT INTO readiness_questions(id,title,question,options_json,position) VALUES('regulations','آشنایی با مقررات','برای فعالیت‌های عمومی مرتبط با نامزدی، تا چه اندازه مسیر بررسی قوانین معتبر و به‌روز را مشخص کرده‌اید؟','[{"label":"هنوز آغاز نکرده‌ام","score":0},{"label":"برنامه اولیه دارم","score":1},{"label":"بخش زیادی را انجام داده‌ام","score":2},{"label":"مستند و قابل اجراست","score":3}]',1) ON CONFLICT(id) DO UPDATE SET title=excluded.title,question=excluded.question,options_json=excluded.options_json,position=excluded.position;
INSERT INTO readiness_questions(id,title,question,options_json,position) VALUES('transparency','شفافیت و مستندسازی','چه میزان برای ثبت و انتشار مستند و قابل بررسی تصمیم‌ها و هزینه‌ها آماده هستید؟','[{"label":"هنوز آغاز نکرده‌ام","score":0},{"label":"برنامه اولیه دارم","score":1},{"label":"بخش زیادی را انجام داده‌ام","score":2},{"label":"مستند و قابل اجراست","score":3}]',2) ON CONFLICT(id) DO UPDATE SET title=excluded.title,question=excluded.question,options_json=excluded.options_json,position=excluded.position;
INSERT INTO readiness_questions(id,title,question,options_json,position) VALUES('planning','برنامه‌ریزی اجرایی','وظایف، مسئولان، موعدها و روش پیگیری فعالیت‌های تیم چقدر روشن و مستند هستند؟','[{"label":"هنوز آغاز نکرده‌ام","score":0},{"label":"برنامه اولیه دارم","score":1},{"label":"بخش زیادی را انجام داده‌ام","score":2},{"label":"مستند و قابل اجراست","score":3}]',3) ON CONFLICT(id) DO UPDATE SET title=excluded.title,question=excluded.question,options_json=excluded.options_json,position=excluded.position;
INSERT INTO readiness_questions(id,title,question,options_json,position) VALUES('privacy','حفاظت از اطلاعات','تا چه اندازه اصول رضایت افراد، کمینه‌سازی داده‌ها و کنترل دسترسی را عملی کرده‌اید؟','[{"label":"هنوز آغاز نکرده‌ام","score":0},{"label":"برنامه اولیه دارم","score":1},{"label":"بخش زیادی را انجام داده‌ام","score":2},{"label":"مستند و قابل اجراست","score":3}]',4) ON CONFLICT(id) DO UPDATE SET title=excluded.title,question=excluded.question,options_json=excluded.options_json,position=excluded.position;
INSERT INTO readiness_questions(id,title,question,options_json,position) VALUES('communication','پاسخ‌گویی و اصلاح اطلاعات','برای پاسخ‌گویی به پرسش‌های عمومی و اصلاح اشتباهات منتشرشده چقدر فرایند مشخص دارید؟','[{"label":"هنوز آغاز نکرده‌ام","score":0},{"label":"برنامه اولیه دارم","score":1},{"label":"بخش زیادی را انجام داده‌ام","score":2},{"label":"مستند و قابل اجراست","score":3}]',5) ON CONFLICT(id) DO UPDATE SET title=excluded.title,question=excluded.question,options_json=excluded.options_json,position=excluded.position;
INSERT INTO readiness_questions(id,title,question,options_json,position) VALUES('security','امنیت حساب‌ها','ورود دومرحله‌ای، بازیابی دسترسی و مسئولیت رخدادهای امنیتی را تا چه اندازه آماده کرده‌اید؟','[{"label":"هنوز آغاز نکرده‌ام","score":0},{"label":"برنامه اولیه دارم","score":1},{"label":"بخش زیادی را انجام داده‌ام","score":2},{"label":"مستند و قابل اجراست","score":3}]',6) ON CONFLICT(id) DO UPDATE SET title=excluded.title,question=excluded.question,options_json=excluded.options_json,position=excluded.position;
